import{_ as a,o as i,c as r,a7 as t}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Office Orbit Privacy Policy","description":"Official Privacy Policy for Office Orbit.","frontmatter":{"title":"Office Orbit Privacy Policy","description":"Official Privacy Policy for Office Orbit.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/office-orbit.md","filePath":"privacy/office-orbit.md"}'),o={name:"privacy/office-orbit.md"};function s(n,e,d,c,l,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy-for-office-orbit" tabindex="-1">Privacy Policy for Office Orbit <a class="header-anchor" href="#privacy-policy-for-office-orbit" aria-label="Permalink to &quot;Privacy Policy for Office Orbit&quot;">​</a></h1><p><strong>Effective Date:</strong> September 8, 2026<br><strong>Last Updated:</strong> September 8, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Office Orbit is a personal work-management application developed by <strong>Anand Raja</strong>. It provides authenticated views of work logs, JIRA references, sprints, allocations, releases, feedback, work links, dashboards, and analytics obtained from the configured Office Orbit API.</p><p>Office Orbit does not include advertising, developer-operated analytics, or third-party tracking SDKs.</p><h2 id="sign-in-information" tabindex="-1">Sign-in information <a class="header-anchor" href="#sign-in-information" aria-label="Permalink to &quot;Sign-in information&quot;">​</a></h2><p>The sign-in screen accepts a username and password. The username supports the device or browser credential manager and is not sent by Office Orbit to its API. The password is sent over HTTPS to the configured authentication endpoint. Office Orbit does not store the plaintext password itself. A browser, Android Autofill service, or Google Password Manager may offer to store credentials under that provider&#39;s settings and privacy terms.</p><h2 id="work-information-retrieved-by-the-app" tabindex="-1">Work information retrieved by the app <a class="header-anchor" href="#work-information-retrieved-by-the-app" aria-label="Permalink to &quot;Work information retrieved by the app&quot;">​</a></h2><p>After authentication, Office Orbit can retrieve:</p><ul><li>Work-log dates, updates, categories, types, work modes, comments, issues, appraisal markers, and related company, team, project, JIRA, and sprint references</li><li>JIRA keys, summaries, statuses, tags, blockers, spillovers, demo details, projects, releases, and sprint relationships</li><li>Sprint dates, capacity, leave and holiday values, allocations, planned days, and notes</li><li>Release items, components, deployment types, versions, branches, dates, notes, and related JIRAs</li><li>Feedback text, dates, sources, types, context, details, follow-up actions, and organizational relationships</li><li>Work-link names, URLs, notes, types, active state, companies, and projects</li><li>Dashboard summaries and analytics derived from these records</li></ul><p>This information may be workplace, confidential, or personal information. Access and retention at the API and its underlying data source are controlled by the service operator, not by the Office Orbit client.</p><h2 id="local-and-device-storage" tabindex="-1">Local and device storage <a class="header-anchor" href="#local-and-device-storage" aria-label="Permalink to &quot;Local and device storage&quot;">​</a></h2><p>On the web, Office Orbit stores the authenticated session in browser session storage. On Android, the session is stored using secure device storage so an active session can be restored.</p><p>Optional PIN protection stores a salted password-based verifier rather than the PIN in plaintext. On supported Android devices, optional biometric unlock uses Android&#39;s biometric system. Office Orbit does not receive or store biometric templates.</p><p>Fetched work records and navigation state are cached in application memory to improve performance. The client clears this cache on sign-out, and it is not designed as persistent storage for source work records. Theme and similar preferences may be stored locally on the device.</p><h2 id="api-processing" tabindex="-1">API processing <a class="header-anchor" href="#api-processing" aria-label="Permalink to &quot;API processing&quot;">​</a></h2><p>Office Orbit connects to its API hosted on Cloudflare Workers. Authentication requests include the entered password. Authenticated requests include an access token and request parameters such as filters, date ranges, pagination cursors, and relationship options. The service also receives ordinary connection information such as IP address, user agent, request time, and requested resource.</p><p>Cloudflare may process network and security information as the hosting provider under its own terms and privacy policy. The API operator can access information held by the API and its underlying work-data source according to that system&#39;s authorization and retention rules.</p><h2 id="web-hosting-and-external-links" tabindex="-1">Web hosting and external links <a class="header-anchor" href="#web-hosting-and-external-links" aria-label="Permalink to &quot;Web hosting and external links&quot;">​</a></h2><p>The browser version is hosted on GitHub Pages. GitHub may process ordinary web-request information such as IP address, browser details, and request logs under its own terms and privacy policy. Office Orbit does not add analytics to the hosted site.</p><p>When you open a work link or another external URL, the destination receives the request and applies its own privacy practices.</p><h2 id="pdf-exports" tabindex="-1">PDF exports <a class="header-anchor" href="#pdf-exports" aria-label="Permalink to &quot;PDF exports&quot;">​</a></h2><p>Office Orbit can create PDF reports from selected work logs. Depending on your choices, a report can contain dates, work updates, categories, types, work modes, comments, issues, appraisal markers, organization names, and JIRA references.</p><p>On the web, the report is downloaded through the browser. On Android, it is temporarily prepared in the app cache and passed to Android&#39;s save or share flow. Exported copies are readable outside Office Orbit and controlled by the destination you select.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information collected by the developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information collected by the developer&quot;">​</a></h2><p>Office Orbit has no developer-operated advertising, analytics, or telemetry endpoint. The developer does not automatically receive your locally stored session, PIN verifier, biometric data, in-memory cache, or exported files.</p><p>The API operator receives authentication and data requests needed to provide the service. If you contact support, the developer receives the information you choose to include and retains it as needed to answer the request.</p><h2 id="android-permissions" tabindex="-1">Android permissions <a class="header-anchor" href="#android-permissions" aria-label="Permalink to &quot;Android permissions&quot;">​</a></h2><p>Office Orbit uses:</p><ul><li><strong>Internet access</strong> to authenticate and retrieve work information from the API</li><li><strong>Biometric authentication</strong> only when you enable biometric app unlock on a supported device</li></ul><p>PDF saving and sharing uses Android&#39;s system flow. The reviewed app does not request location, contacts, phone, SMS, camera, microphone, call-log, notification, or broad storage permissions.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Signing out clears the locally stored session and in-memory data cache. Expired or invalid sessions are discarded. Disabling PIN protection removes the local PIN and biometric preference.</p><p>You can remove all app-held Android data by clearing Office Orbit storage in Android settings or uninstalling the app. In a browser, close the browser session and clear the site&#39;s storage and cache.</p><p>These actions do not delete work records held by the API or its underlying data source, support emails, or PDF files saved or shared elsewhere.</p><h2 id="workplace-responsibility" tabindex="-1">Workplace responsibility <a class="header-anchor" href="#workplace-responsibility" aria-label="Permalink to &quot;Workplace responsibility&quot;">​</a></h2><p>Use Office Orbit only with work information you are authorized to access. Follow applicable employer policies and privacy, confidentiality, security, intellectual-property, and records-retention requirements.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s privacy&quot;">​</a></h2><p>Office Orbit is a workplace productivity tool and is not directed to children.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to this policy&quot;">​</a></h2><p>This policy may be updated when Office Orbit&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',43)])])}const u=a(o,[["render",s]]);export{f as __pageData,u as default};
